(()=>{'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const app=$('#app'),toastEl=$('#toast');
let token='',items=[],active='overview',editing=null,kind='url',qr=null,payments=[],bankExtras=[],appLinks=[],mapLinks=[],draftId='',customIdValue='',customIdTouched=false,draftName='',draftStyle=null,generatedSuffix=String(Math.floor(1000+Math.random()*9000)),draftData={},lang='en',theme='dark',drawerOpen=false;
const types={url:'Link',phone:'Phone',text:'Text',bank:'Bank details',app:'App',smartmap:'Smart map',video:'Video Marketing',payments:'Multi Payments'};
const typeIcons={url:'fa-link',phone:'fa-phone',text:'fa-align-left',bank:'fa-building-columns',app:'fa-mobile-screen-button',smartmap:'fa-map-location-dot',video:'fa-circle-play',payments:'fa-credit-card'};
const id=()=>Math.random().toString(36).slice(2,7)+Date.now().toString(36).slice(-4);
const slugify=s=>String(s||'qr').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,36)||'qr';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name)=>`<i class="fa-solid ${name}" aria-hidden="true"></i>`;
const toast=s=>{toastEl.textContent=s;toastEl.classList.add('show');setTimeout(()=>toastEl.classList.remove('show'),2800)};
const cache=()=>localStorage.setItem('cladx-privet-cache',JSON.stringify(items));
const headers=()=>({'content-type':'application/json',...(token?{authorization:'Bearer '+token}:{})});
async function api(path,opts={}){let r=await fetch('/api/'+path,{...opts,headers:{...headers(),...(opts.headers||{})}});let d=await r.json().catch(()=>({error:'Invalid server response'}));if(!r.ok)throw Error(d.error||'Request failed');return d}
function brand(){return `<div class="brand"><img src="/assets/logo.webp" alt="CLADx"><div><strong>CLADx PRIVET QR</strong><small>AGENCY WORKSPACE</small></div></div>`}
function login(){app.innerHTML=`<div class="login-page"><header class="login-header"><img src="/assets/logo.webp" alt="CLADx"><div class="top-actions"><button class="icon-btn" id="loginLang" title="Change language">${icon('fa-language')}</button><button class="icon-btn" id="loginTheme" title="Light mode">${icon('fa-sun')}</button></div></header><div class="login-content"><section class="login-form-side"><form class="login-card" id="loginForm"><h1>Welcome back.</h1><p>Sign in to manage your dynamic QR experiences.</p><div class="field"><label>Admin password</label><input id="password" type="password" autocomplete="current-password" placeholder="Enter your access password" required></div><button class="btn" type="submit">Access dashboard ${icon('fa-arrow-right')}</button><div class="hint" style="text-align:center;margin-top:18px">Private workspace · CLADx Agency</div></form></section><section class="login-art"><svg viewBox="0 0 620 480" role="img" aria-label="Phone scanning a QR code"><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#00b5d9"/><stop offset="1" stop-color="#00ffff"/></linearGradient></defs><circle cx="310" cy="240" r="190" fill="url(#g)" opacity=".10"/><rect x="185" y="40" width="250" height="400" rx="34" fill="#10191e" stroke="url(#g)" stroke-width="7"/><rect x="205" y="76" width="210" height="320" rx="18" fill="#f8ffff"/><g fill="#071216"><path d="M232 102h66v66h-66z M244 114h42v42h-42z M250 120h30v30h-30z M321 102h66v66h-66z M333 114h42v42h-42z M339 120h30v30h-30z M232 272h66v66h-66z M244 284h42v42h-42z M250 290h30v30h-30z M315 190h18v18h-18z M350 190h18v18h-18z M315 226h18v18h-18z M386 226h10v10h-10z M350 260h18v18h-18z M386 292h10v10h-10z M315 326h18v18h-18z M350 326h42v18h-42z"/></g><path d="M218 222h184" stroke="url(#g)" stroke-width="6" stroke-linecap="round"/><path d="M110 180l45-45m0 0v34m0-34h-34M460 300l45 45m0 0h-34m34 0v-34" fill="none" stroke="url(#g)" stroke-width="9" stroke-linecap="round" stroke-linejoin="round"/><circle cx="310" cy="418" r="8" fill="url(#g)"/></svg><h2>One scan. Endless possibilities.</h2><p>Smart, editable QR experiences for your business.</p></section></div><footer class="login-footer">Developed by <a href="https://cladxagency.com" target="_blank" rel="noopener">CLADx</a></footer></div>`;
$('#loginForm').onsubmit=async e=>{e.preventDefault();try{let r=await fetch('/api/auth/login',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({password:$('#password').value})});let d=await r.json();if(!r.ok)throw Error(d.error||'Login failed');token=d.token;sessionStorage.setItem('cladx-session',token);await load();render()}catch(e){toast(e.message)}};
$('#loginLang').onclick=()=>{lang=lang==='en'?'ar':'en';document.documentElement.dir=lang==='ar'?'rtl':'ltr';toast(lang==='ar'?'تم اختيار العربية':'English selected')};
$('#loginTheme').onclick=()=>{theme=theme==='dark'?'light':'dark';document.body.classList.toggle('light',theme==='light')};
}
function navItems(){return [['overview','Overview','fa-chart-pie'],['codes','QR library','fa-qrcode'],['create','Create QR','fa-circle-plus'],['backup','Backup','fa-cloud-arrow-up'],['settings','Settings','fa-gear']]}
function layout(){app.innerHTML=`<div class="shell"><aside class="sidebar" id="sidebar"><div class="side-brand"><img src="/assets/logo.webp" alt="CLADx"><div><strong>CLADx PRIVET QR</strong><small>AGENCY WORKSPACE</small></div></div><nav class="nav">${navItems().map(([k,n,i])=>`<button data-page="${k}"><span class="ico">${icon(i)}</span><span>${n}</span></button>`).join('')}</nav><div class="side-foot"><div class="sync">${icon('fa-cloud')} Cloud sync</div><button id="logout">${icon('fa-right-from-bracket')} Sign out</button></div></aside><div class="mobile-scrim" id="scrim"></div><main class="main"><header class="topbar"><div class="top-heading"><button class="icon-btn mobile-menu" id="menu" aria-label="Open menu">${icon('fa-bars')}</button><div><div class="eyebrow">CLADx / PRIVATE QR MANAGEMENT</div><h1 id="pageTitle">Overview</h1></div></div><div class="top-actions"><button class="btn" id="newBtn">+ QR</button><button class="icon-btn desktop-only" id="langBtn" title="Language">${icon('fa-language')}</button><button class="icon-btn desktop-only" id="themeBtn" title="Light mode">${icon('fa-sun')}</button><button class="avatar" id="avatarBtn" aria-label="Account menu">C</button></div></header><div id="view"></div><footer class="app-footer">Developed by <a href="https://cladxagency.com" target="_blank" rel="noopener">CLADx</a></footer></main><nav class="bottom-nav">${navItems().map(([k,n,i])=>`<button data-page="${k}">${icon(i)}<span>${n.split(' ')[0]}</span></button>`).join('')}</nav><div class="drawer-scrim" id="drawerScrim"></div><aside class="account-drawer" id="accountDrawer"><div class="drawer-head"><b>CLADx Workspace</b><button class="icon-btn" id="drawerClose">${icon('fa-xmark')}</button></div>${[['Company profile','fa-building'],['Notifications','fa-bell'],['Backup','fa-cloud-arrow-up'],['Settings','fa-gear'],['Sign out','fa-right-from-bracket'],['About project','fa-circle-info'],['CLADx Support','fa-headset']].map(([n,i])=>`<button class="drawer-item" data-drawer="${n}">${n==='Notifications'?'<img class="notify-image" src="/assets/notifications.webp" alt="">':icon(i)}<span>${n}</span>${n==='Notifications'?'<b class="notify-count" id="notifyCount">0</b>':''}</button>`).join('')}</aside></div>`;
$$('[data-page]').forEach(b=>b.onclick=()=>b.dataset.page==='create'?startNewQR():go(b.dataset.page));$('#newBtn').onclick=startNewQR;$('#logout').onclick=logout;$('#menu').onclick=()=>toggleSidebar();$('#scrim').onclick=closeSidebar;$('#avatarBtn').onclick=openDrawer;$('#drawerScrim').onclick=closeDrawer;$('#drawerClose').onclick=closeDrawer;$('#langBtn').onclick=toggleLanguage;$('#themeBtn').onclick=toggleTheme;$$('[data-drawer]').forEach(b=>b.onclick=()=>{let n=b.dataset.drawer;closeDrawer();if(n==='Sign out')logout();else if(n==='Backup')go('backup');else if(n==='Settings'||n==='Company profile')go('settings');else if(n==='Notifications')showNotifications();else if(n==='CLADx Support')window.open('https://cladxagency.com','_blank','noopener');else showAbout()})}
function toggleSidebar(){$('#sidebar').classList.toggle('open');$('#scrim').classList.toggle('show')}
function closeSidebar(){$('#sidebar')?.classList.remove('open');$('#scrim')?.classList.remove('show')}
function openDrawer(){$('#accountDrawer').classList.add('open');$('#drawerScrim').classList.add('show')}
function closeDrawer(){$('#accountDrawer')?.classList.remove('open');$('#drawerScrim')?.classList.remove('show')}
function applyLanguage(){document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';const dict={'Overview':'نظرة عامة','QR library':'مكتبة QR','Create QR':'إنشاء QR','Backup':'نسخ احتياطي','Settings':'الإعدادات','Sign out':'تسجيل الخروج','QR code':'رمز QR','QR name':'اسم رمز QR','Short link ID':'معرّف الرابط المختصر','Experience type':'نوع التجربة','QR appearance':'مظهر QR','Copy link':'نسخ الرابط','Share':'مشاركة','Back to library':'العودة للمكتبة','All QR experiences':'كل رموز QR','Search by name or ID…':'ابحث بالاسم أو المعرّف…','Recent QR experiences':'أحدث رموز QR','View all':'عرض الكل','Scan analytics':'إحصاءات المسح','TOTAL QR EXPERIENCES':'إجمالي رموز QR','ACTIVE LINKS':'الروابط النشطة','LINK TYPES':'أنواع الروابط','MOST USED TYPE':'النوع الأكثر استخدامًا','TOTAL SCANS':'إجمالي عمليات المسح','UNIQUE QR SCANNED':'رموز QR التي تم مسحها','RECENT SCANS':'عمليات المسح الأخيرة','Backup now':'نسخ احتياطي الآن','Restore from hosting':'استعادة من الاستضافة','Workspace settings':'إعدادات مساحة العمل','Welcome back.':'مرحبًا بعودتك.','Admin password':'كلمة مرور المسؤول','Access dashboard':'دخول لوحة التحكم','Notifications':'الإشعارات','Company profile':'ملف الشركة','About project':'عن المشروع','CLADx Support':'دعم CLADx','Multi Payments':'مدفوعات متعددة','Bank details':'بيانات الحساب البنكي','Video Marketing':'التسويق بالفيديو','Smart map':'الخريطة الذكية','App':'التطبيق','Link':'رابط','Phone':'الهاتف','Text':'نص','Destination URL':'رابط الوجهة','Text content':'محتوى النص','Phone number':'رقم الهاتف','Account holder':'صاحب الحساب','Bank name':'اسم البنك','Account / IBAN':'الحساب / IBAN','Branch / SWIFT':'الفرع / SWIFT','Additional details':'تفاصيل إضافية','Custom bank fields':'حقول بنكية مخصصة','Page title':'عنوان الصفحة','Description':'الوصف','Page logo URL':'رابط شعار الصفحة','Payment methods':'طرق الدفع','Application store links (add at least one)':'روابط متاجر التطبيقات (أضف رابطًا واحدًا على الأقل)','Company branches':'فروع الشركة','QR pattern':'نمط QR','Finder dots':'نقاط زوايا QR','Finder frames':'إطارات زوايا QR','Center logo':'الشعار الأوسط','Logo size':'حجم الشعار','Dots':'النقاط','Finder frame':'إطار الزوايا','Finder center':'مركز الزوايا','Background':'الخلفية','Transparent background':'خلفية شفافة','No logo':'بدون شعار','Add logo':'إضافة شعار','CLADx logo':'شعار CLADx','Create QR':'إنشاء QR','Edit QR code':'تعديل QR','Save changes':'حفظ التعديلات','Download backup':'تنزيل نسخة احتياطية','Import backup':'استيراد نسخة احتياطية','Download PNG':'تنزيل PNG','Restore cloud backup':'استعادة النسخة السحابية','Build a dynamic QR':'إنشاء رمز QR ديناميكي','One permanent short link. Edit the destination and styling whenever needed.':'رابط مختصر ثابت. يمكنك تعديل الوجهة والتصميم في أي وقت.','The short URL remains the same when you edit its destination or design.':'يظل الرابط المختصر كما هو عند تعديل الوجهة أو التصميم.','Your QR library is ready.':'مكتبة QR جاهزة.','Create a dynamic QR code to get started.':'أنشئ رمز QR ديناميكي للبدء.','Add a field':'إضافة حقل','Add payment method':'إضافة وسيلة دفع','Add app link':'إضافة رابط تطبيق','Add branch':'إضافة فرع','Video URL (YouTube, Facebook, Instagram or TikTok)':'رابط فيديو (يوتيوب أو فيسبوك أو إنستجرام أو تيك توك)','QR scan milestones':'مراحل عدد المسح','Cloud sync':'مزامنة سحابية','Latest three codes in your workspace.':'أحدث ثلاثة رموز في مساحة العمل.','Manage destinations, pause or export individual dynamic destinations.':'إدارة الوجهات وإيقافها مؤقتًا أو تصديرها.','Share page':'مشاركة الصفحة','Copy text':'نسخ النص','Call':'اتصال','No notifications yet.':'لا توجد إشعارات حتى الآن.','Sign in to manage your dynamic QR experiences.':'سجّل الدخول لإدارة رموز QR الديناميكية.','Private workspace · CLADx Agency':'مساحة عمل خاصة · وكالة CLADx','Admin password':'كلمة مرور المسؤول','Enter your access password':'أدخل كلمة مرور الدخول','Overview':'نظرة عامة','Name':'الاسم','Type':'النوع','Short link':'الرابط المختصر','Status':'الحالة','Updated':'آخر تحديث','Actions':'الإجراءات','Active':'نشط','Inactive':'غير نشط','Paused':'متوقف مؤقتًا','Edit':'تعديل','Copy':'نسخ','Delete':'حذف','Build a dynamic QR':'إنشاء رمز QR ديناميكي','Colors and central CLADx mark.':'الألوان وشعار CLADx في المنتصف.','Live QR preview':'معاينة QR مباشرة','Download PNG':'تنزيل PNG','Download SVG':'تنزيل SVG','Download WEBP':'تنزيل WEBP','Download PDF':'تنزيل PDF','Add a name first':'أضف اسمًا أولًا','Choose an experience type':'اختر نوع التجربة','No application link is available.':'لا يوجد رابط تطبيق متاح.','QR scans and usage thresholds.':'عمليات مسح QR وحدود الاستخدام.','Private agency workspace':'مساحة عمل خاصة بالوكالة','Public base URL':'الرابط الأساسي العام','KV binding':'ربط KV','Admin authentication':'مصادقة المسؤول','The browser cache is updated together with every successful Backup now or Restore from hosting operation.':'يتم تحديث التخزين المحلي مع كل عملية نسخ أو استعادة ناجحة.','Backup completed':'اكتمل النسخ الاحتياطي','Backup failed':'فشل النسخ الاحتياطي','Import failed':'فشل الاستيراد','Restore failed':'فشلت الاستعادة','Your QR library is ready.':'مكتبة QR جاهزة.','Latest three codes in your workspace.':'أحدث ثلاثة رموز في مساحة العمل.','Search, edit, pause or export individual destinations.':'ابحث وعدّل وأوقف مؤقتًا أو صدّر الوجهات.','Link':'رابط','Phone':'الهاتف','Text':'نص','Bank details':'بيانات الحساب البنكي','App':'التطبيق','Smart map':'الخريطة الذكية','Video Marketing':'التسويق بالفيديو','Multi Payments':'مدفوعات متعددة','Application store links (add at least one)':'روابط متاجر التطبيقات (أضف رابطًا واحدًا على الأقل)','Company branches':'فروع الشركة','A branded, responsive video page will be created. Platform autoplay and ad policies are controlled by the video provider and device browser.':'سيتم إنشاء صفحة فيديو متجاوبة بهوية الشركة. تتحكم منصة الفيديو والمتصفح في التشغيل التلقائي والإعلانات.'};const reverse=Object.fromEntries(Object.entries(dict).map(([a,b])=>[b,a]));const map=lang==='ar'?dict:reverse;const walk=document.createTreeWalker(app,NodeFilter.SHOW_TEXT);let n;while(n=walk.nextNode()){let v=n.nodeValue.trim();if(map[v])n.nodeValue=n.nodeValue.replace(v,map[v])}$$('input,textarea').forEach(el=>{let pm={'Enter your access password':'أدخل كلمة مرور الدخول','Search by name or ID…':'ابحث بالاسم أو المعرّف…'};let rm=Object.fromEntries(Object.entries(pm).map(([a,b])=>[b,a]));let d=lang==='ar'?pm:rm;if(d[el.placeholder])el.placeholder=d[el.placeholder]})}
function toggleLanguage(){lang=lang==='en'?'ar':'en';applyLanguage();toast(lang==='ar'?'تم تفعيل العربية':'English interface selected')}
function toggleTheme(){theme=theme==='dark'?'light':'dark';document.body.classList.toggle('light',theme==='light')}
const $$$=s=>[...document.querySelectorAll(s)];
async function load(){try{let d=await api('links');items=d.items||[];cache()}catch(e){items=JSON.parse(localStorage.getItem('cladx-privet-cache')||'[]');toast('Cloud sync unavailable — showing local cached data')}}
async function logout(){try{await api('auth/logout',{method:'POST'})}catch{}token='';sessionStorage.removeItem('cladx-session');login()}
function startNewQR(){editing=null;kind='url';draftData={};draftName='';draftStyle=null;customIdValue='';customIdTouched=false;generatedSuffix=String(Math.floor(1000+Math.random()*9000));draftId=id();go('create')}
function go(p){active=p;closeSidebar();closeDrawer();render()}
function render(){if(!$('#view'))layout();$$('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===active));$$('.bottom-nav [data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===active));let titles={overview:'Overview',codes:'QR library',create:editing?'Edit QR code':'Create QR code',backup:'Backup & restore',settings:'Workspace settings'};$('#pageTitle').textContent=titles[active]||'Overview';({overview,codes:library,create:editor,backup,settings}[active]||overview)();applyLanguage();loadNotificationCount()}
function table(list){if(!list.length)return `<div class="card empty"><strong>Your QR library is ready.</strong>Create your first dynamic QR code to get started.</div>`;return `<div class="table-wrap"><table class="table"><thead><tr><th>Name</th><th>Type</th><th>Short link</th><th>Status</th><th>Updated</th><th>Actions</th></tr></thead><tbody>${list.map(x=>`<tr><td><b>${esc(x.name)}</b><div class="hint">${esc(x.id)}</div></td><td><span class="type-tag">${icon(typeIcons[x.type]||'fa-qrcode')} ${esc(types[x.type]||x.type)}</span></td><td><a class="shortlink" target="_blank" href="/go/${encodeURIComponent(x.id)}">/go/${esc(x.id)}</a></td><td><span class="status ${x.active===false?'paused':''}">${x.active===false?'Inactive':'Active'}</span></td><td>${x.updatedAt?new Date(x.updatedAt).toLocaleDateString():'—'}</td><td><div class="actions"><button class="icon-btn" data-edit="${esc(x.id)}" title="Edit">${icon('fa-pen')}</button><button class="icon-btn" data-copy="${esc(x.id)}" title="Copy">${icon('fa-copy')}</button><button class="icon-btn" data-toggle="${esc(x.id)}" title="Toggle">${icon(x.active===false?'fa-toggle-off':'fa-toggle-on')}</button><button class="icon-btn" data-delete="${esc(x.id)}" title="Delete">${icon('fa-trash')}</button></div></td></tr>`).join('')}</tbody></table></div>`}
function bindRows(){ $$('[data-edit]').forEach(b=>b.onclick=()=>{editing=items.find(x=>x.id===b.dataset.edit);kind=editing?.type||'url';draftData={};draftName=editing?.name||'';draftStyle=editing?.style||null;customIdValue=editing?.id||'';customIdTouched=true;go('create')});$$('[data-copy]').forEach(b=>b.onclick=()=>copyText(location.origin+'/go/'+b.dataset.copy));$$('[data-toggle]').forEach(b=>b.onclick=async()=>{let x=items.find(x=>x.id===b.dataset.toggle);if(!x)return;x.active=x.active===false;try{let d=await api('links/'+x.id,{method:'PUT',body:JSON.stringify(x)});Object.assign(x,d.item||x);cache();toast(x.active?'QR activated':'QR paused');render()}catch(e){x.active=!x.active;toast(e.message)}});$$('[data-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('Delete this QR experience permanently?'))return;try{await api('links/'+b.dataset.delete,{method:'DELETE'});items=items.filter(x=>x.id!==b.dataset.delete);cache();toast('QR deleted');render()}catch(e){toast(e.message)}})}
function copyText(s){navigator.clipboard?.writeText(s).then(()=>toast('Copied')).catch(()=>toast('Clipboard unavailable'))}
function overview(){let activeCount=items.filter(x=>x.active!==false).length,counts={};items.forEach(x=>counts[x.type]=(counts[x.type]||0)+1);let top=Object.entries(counts).sort((a,b)=>b[1]-a[1])[0];$('#view').innerHTML=`<div class="grid stats"><div class="card"><div class="stat-label">TOTAL QR EXPERIENCES</div><div class="stat-value">${items.length}</div><div class="stat-note">All created records</div></div><div class="card"><div class="stat-label">ACTIVE LINKS</div><div class="stat-value">${activeCount}</div><div class="stat-note">Available to visitors</div></div><div class="card"><div class="stat-label">LINK TYPES</div><div class="stat-value">${Object.keys(counts).length}</div><div class="stat-note">Across your workspace</div></div><div class="card"><div class="stat-label">MOST USED TYPE</div><div class="stat-value" style="font-size:23px">${top?esc(types[top[0]]):'—'}</div><div class="stat-note">${top?top[1]+' QR codes':'No data yet'}</div></div></div><div class="section-head"><div><h2>Recent QR experiences</h2><p>Latest three codes in your workspace.</p></div><button class="btn ghost" id="viewAll">View all</button></div>${table(items.slice().sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0)).slice(0,3))}<div class="section-head"><div><h2>Scan analytics</h2><p>Scan counts and usage by QR type.</p></div><button class="btn ghost" id="refreshStats">${icon('fa-rotate')} Refresh</button></div><div class="grid stats" id="analyticsStats"><div class="card"><div class="stat-label">TOTAL SCANS</div><div class="stat-value">—</div><div class="stat-note">Loading scan data</div></div></div><div class="card"><h3>Usage by QR type</h3><div id="typeAnalytics" class="analytics-bars">Loading…</div></div>`;$('#viewAll').onclick=()=>go('codes');bindRows();$('#refreshStats').onclick=loadAnalytics;loadAnalytics()}
async function loadAnalytics(){try{let d=await api('analytics');let total=d.totalScans||0;$('#analyticsStats').innerHTML=`<div class="card"><div class="stat-label">TOTAL SCANS</div><div class="stat-value">${total}</div><div class="stat-note">Recorded visits to active QR links</div></div><div class="card"><div class="stat-label">UNIQUE QR SCANNED</div><div class="stat-value">${d.scannedCodes||0}</div><div class="stat-note">QR codes with at least one scan</div></div><div class="card"><div class="stat-label">TOP QR</div><div class="stat-value" style="font-size:20px">${esc(d.top?.name||'—')}</div><div class="stat-note">${d.top?.scans||0} scans</div></div><div class="card"><div class="stat-label">RECENT SCANS</div><div class="stat-value">${d.recent24h||0}</div><div class="stat-note">Last 24 hours</div></div>`;$('#typeAnalytics').innerHTML=Object.entries(d.byType||{}).map(([k,v])=>`<div class="bar-row"><span>${esc(types[k]||k)}</span><div><i style="width:${total?Math.max(2,v/total*100):0}%"></i></div><b>${v}</b></div>`).join('')||'No scans yet'}catch(e){$('#analyticsStats').innerHTML=`<div class="card hint">Analytics will appear after your first QR scan. ${esc(e.message)}</div>`}}
function library(){$('#view').innerHTML=`<div class="section-head"><div><h2>All QR experiences</h2><p>Search, edit, pause or export individual destinations.</p></div><div class="toolbar"><input class="search" id="search" placeholder="Search by name or ID…"></div></div><div id="libTable">${table(items)}</div>`;$('#search').oninput=()=>{$('#libTable').innerHTML=table(items.filter(x=>(x.name+' '+x.id+' '+x.type).toLowerCase().includes($('#search').value.toLowerCase())));bindRows()};bindRows()}
function editor(){let x=editing?{...editing,name:draftName,style:draftStyle||editing.style}:{id:draftId||id(),name:draftName||'',type:kind||'url',data:{url:''},style:draftStyle||{dot:'#000000',corner:'#00b5d9',cornerDot:'#000000',background:'#ffffff',logo:'cladx'},active:true};kind=kind||'url';draftId=x.id;const d=draftData[kind]||(editing&&editing.type===kind?editing.data||{}:{});payments=d.payments||[];bankExtras=d.extraFields||[];appLinks=d.links||[{name:'Apple App Store',url:'',platform:'ios'},{name:'Google Play',url:'',platform:'android'},{name:'Other devices',url:'',platform:'other'}];mapLinks=d.branches||[{name:'Main branch',url:'',lat:'',lng:''}];if(editing&&!customIdValue)customIdValue=editing.id;window.selectedPattern=x.style?.dotType||'rounded';window.selectedFinderDot=x.style?.cornerDotType||'dot';window.selectedFinderFrame=x.style?.cornerType||'extra-rounded';window.selectedLogo=x.style?.logo==='none'?'none':x.style?.logo==='custom'?'custom':'cladx';$('#view').innerHTML=`<div class="section-head"><div><h2>${editing?'Update an experience':'Build a dynamic QR'}</h2><p>Permanent short link. Edit the destination and styling whenever needed.</p></div><button class="btn ghost" id="cancelEdit">${icon('fa-arrow-left')} Back to library</button></div><div class="editor"><section class="card"><div class="field"><label>QR name</label><input id="qrName" value="${esc(x.name)}" placeholder="e.g. Main website / Branch payment"></div><div class="field"><label>Short link ID</label><input id="customId" value="${esc(editing?x.id:customIdValue)}" placeholder="english-name-1234"><small class="hint">Suggested from the QR name; you can customize it.</small></div><div class="field"><label>Experience type</label><div class="type-grid">${Object.entries(types).map(([k,v])=>`<button type="button" data-type="${k}" class="${kind===k?'active':''}">${icon(typeIcons[k])}<span>${v}</span></button>`).join('')}</div></div><div id="typeFields">${typeFields(d)}</div><div class="section-head"><div><h2>QR appearance</h2><p>Separate finder colors, patterns and center logo.</p></div></div><div class="color-row four-col"><div class="field"><label>Dots</label><input type="color" id="dotColor" value="${x.style?.dot||'#000000'}"></div><div class="field"><label>Finder frame</label><input type="color" id="cornerColor" value="${x.style?.corner||'#00b5d9'}"></div><div class="field"><label>Finder center</label><input type="color" id="cornerDotColor" value="${x.style?.cornerDot||'#000000'}"></div><div class="field"><label>Background</label><input type="color" id="bgColor" value="${x.style?.background||'#ffffff'}"></div></div><label class="check-row"><input type="checkbox" id="transparentBg" ${x.style?.transparent?'checked':''}> Transparent background</label><div class="field"><label>QR pattern</label><div class="choice-grid" id="patternChoices">${[['square','Square'],['dots','Dots'],['rounded','Rounded'],['classy','Classy'],['classy-rounded','Classy round'],['extra-rounded','Extra round']].map(([v,n])=>`<button type="button" data-pattern="${v}" class="${(x.style?.dotType||'rounded')===v?'selected':''}">${patternIcon(v)}<small>${n}</small></button>`).join('')}</div></div><div class="field"><label>Finder dots</label><div class="choice-grid" id="finderDotChoices">${[['square','Square'],['dot','Dot']].map(([v,n])=>`<button type="button" data-finderdot="${v}" class="${(x.style?.cornerDotType||'dot')===v?'selected':''}">${patternIcon(v)}<small>${n}</small></button>`).join('')}</div></div><div class="field"><label>Finder frames</label><div class="choice-grid" id="finderFrameChoices">${[['square','Square'],['dot','Dot'],['extra-rounded','Rounded']].map(([v,n])=>`<button type="button" data-finderframe="${v}" class="${(x.style?.cornerType||'extra-rounded')===v?'selected':''}">${patternIcon(v)}<small>${n}</small></button>`).join('')}</div></div><div class="field"><label>Center logo</label><div class="choice-grid logo-choices"><button type="button" data-logo="none" class="${x.style?.logo==='none'?'selected':''}">${icon('fa-ban')}<small>No logo</small></button><button type="button" data-logo="cladx" class="${(!x.style?.logo||x.style?.logo==='cladx'||x.style?.logo===true)?'selected':''}"><img src="/assets/qr-cladx-logo-icon.webp"><small>CLADx logo</small></button><button type="button" data-logo="custom" class="${x.style?.logo==='custom'?'selected':''}">${icon('fa-image')}<small>Add logo</small></button></div><div class="field hidden" id="customLogoWrap"><label>Logo image URL</label><input id="customLogo" value="${esc(x.style?.customLogo||'')}" placeholder="https://example.com/logo.png"></div><div class="field"><label>Logo size</label><input id="logoSize" type="range" min=".12" max=".32" step=".01" value="${x.style?.logoSize||.22}"></div></div><button class="btn" id="saveQR">${editing?'Save changes':'Create QR'} ${icon('fa-arrow-right')}</button><p class="hint" style="margin-top:13px">The short URL remains the same when you edit its destination or design.</p></section><aside class="preview-column">${['payments','video','bank','app'].includes(kind)?`<div class="card page-preview-card"><div class="eyebrow">LIVE DESTINATION PAGE PREVIEW</div><div id="destinationPagePreview"></div></div>`:''}<div class="card preview-card"><div class="eyebrow">LIVE QR PREVIEW</div><div class="qr-stage" id="qrStage"></div><b id="previewName">${esc(x.name||'Your QR experience')}</b><p class="hint" id="previewUrl">${location.origin}/go/${esc(x.id)}</p><div class="toolbar center"><button class="btn ghost" id="copyDynamicLink">${icon('fa-copy')} Copy link</button><button class="btn ghost" id="shareDynamicLink">${icon('fa-share-nodes')} Share</button></div><div class="toolbar center"><button class="btn ghost" id="downloadPng">PNG</button><button class="btn ghost" id="downloadSvg">SVG</button><button class="btn ghost" id="downloadWebp">WEBP</button><button class="btn ghost" id="downloadPdf">PDF</button></div></div></aside></div>`;
$('#cancelEdit').onclick=()=>{editing=null;go('codes')};
$$('[data-type]').forEach(b=>b.onclick=()=>{try{draftData[kind]=readData()}catch{}try{draftStyle=currentStyle()}catch{}draftName=$('#qrName').value;kind=b.dataset.type;editor()});
$('#qrName').oninput=()=>{draftName=$('#qrName').value;if(!editing&&!customIdTouched){let suggested=slugify($('#qrName').value);customIdValue=suggested?`${suggested}-${generatedSuffix}`:'';$('#customId').value=customIdValue;draftId=customIdValue||draftId;$('#previewUrl').textContent=location.origin+'/go/'+draftId;preview()}$('#previewName').textContent=$('#qrName').value||'Your QR experience';updateDestinationPagePreview()};
$('#customId').oninput=()=>{customIdTouched=true;customIdValue=slugify($('#customId').value);$('#customId').value=customIdValue;draftId=customIdValue||draftId;$('#previewUrl').textContent=location.origin+'/go/'+draftId;preview()};
['dotColor','cornerColor','cornerDotColor','bgColor','transparentBg','dotType','logo','customLogo','logoSize'].forEach(k=>{let el=$('#'+k);if(el)el.onchange=preview});
$$('[data-pattern]').forEach(b=>b.onclick=()=>selectChoice('[data-pattern]',b,'selected',()=>{window.selectedPattern=b.dataset.pattern;preview()}));
$$('[data-finderdot]').forEach(b=>b.onclick=()=>selectChoice('[data-finderdot]',b,'selected',()=>{window.selectedFinderDot=b.dataset.finderdot;preview()}));
$$('[data-finderframe]').forEach(b=>b.onclick=()=>selectChoice('[data-finderframe]',b,'selected',()=>{window.selectedFinderFrame=b.dataset.finderframe;preview()}));
$$('[data-logo]').forEach(b=>b.onclick=()=>{selectChoice('[data-logo]',b,'selected',()=>{window.selectedLogo=b.dataset.logo;$('#customLogoWrap').classList.toggle('hidden',b.dataset.logo!=='custom');preview()})});
if(x.style?.logo==='custom')$('#customLogoWrap').classList.remove('hidden');
if(kind==='bank'){drawBankExtras();$$('[data-copyfield]').forEach(b=>b.onclick=()=>copyText($('#'+b.dataset.copyfield).value));$('#addBankField').onclick=()=>{bankExtras.push({label:'',value:''});drawBankExtras();updateDestinationPagePreview()}}
if(kind==='payments'){drawPayments();$('#addPayment').onclick=()=>{payments.push({name:'',url:'',logo:''});drawPayments();preview();updateDestinationPagePreview()}}
if(kind==='app'){drawAppLinks();$('#addAppLink').onclick=()=>{appLinks.push({name:'Google Play',url:'',platform:'android'});drawAppLinks();updateDestinationPagePreview()}}
if(kind==='smartmap'){drawMapLinks();$('#addMapLink').onclick=()=>{mapLinks.push({name:'Main branch',url:'',lat:'',lng:''});drawMapLinks()}}
$('#typeFields').addEventListener('input',()=>{preview();updateDestinationPagePreview()});$('#typeFields').addEventListener('change',()=>{preview();updateDestinationPagePreview()});
$('#saveQR').onclick=saveQR;
$('#copyDynamicLink').onclick=()=>copyText(location.origin+'/go/'+draftId);
$('#shareDynamicLink').onclick=shareLink;
$('#downloadPng').onclick=()=>downloadQr('png');$('#downloadSvg').onclick=()=>downloadQr('svg');$('#downloadWebp').onclick=()=>downloadQr('webp');$('#downloadPdf').onclick=downloadPdf;
preview();updateDestinationPagePreview();
}
function selectChoice(sel,b,cl,cb){$$(sel).forEach(x=>x.classList.remove(cl));b.classList.add(cl);cb()}
function patternIcon(v){return `<span class="pattern-symbol ${esc(v)}"><i></i><i></i><i></i><i></i></span>`}
function typeFields(d){if(kind==='url')return `<div class="field"><label>Destination URL</label><input id="url" type="url" value="${esc(d.url||'')}" placeholder="https://example.com" required></div>`;if(kind==='text')return `<div class="field"><label>Text content</label><textarea id="text" placeholder="Enter text">${esc(d.text||'')}</textarea></div>`;if(kind==='phone')return `<div class="field"><label>Phone number</label><input id="phone" type="tel" value="${esc(d.phone||'')}" placeholder="+20 100 000 0000"></div>`;if(kind==='bank')return `<div class="field"><label>Account holder</label><div class="copy-field"><input id="holder" value="${esc(d.holder||'')}"><button class="icon-btn" data-copyfield="holder">${icon('fa-copy')}</button></div></div><div class="field"><label>Bank name</label><div class="copy-field"><input id="bankName" value="${esc(d.bankName||'')}"><button class="icon-btn" data-copyfield="bankName">${icon('fa-copy')}</button></div></div><div class="field"><label>Account / IBAN</label><div class="copy-field"><input id="account" value="${esc(d.account||'')}"><button class="icon-btn" data-copyfield="account">${icon('fa-copy')}</button></div></div><div class="field"><label>Branch / SWIFT</label><div class="copy-field"><input id="branch" value="${esc(d.branch||'')}"><button class="icon-btn" data-copyfield="branch">${icon('fa-copy')}</button></div></div><div class="field"><label>Additional details</label><div class="copy-field"><textarea id="extra">${esc(d.extra||'')}</textarea><button class="icon-btn" data-copyfield="extra">${icon('fa-copy')}</button></div></div><div class="field"><label>Custom bank fields</label><div id="bankExtraRows"></div><button type="button" class="btn ghost" id="addBankField">+ Add field</button></div>`;if(kind==='payments')return `<div class="field"><label>Page title</label><input id="pageTitleInput" value="${esc(d.title||'Payment options')}"></div><div class="field"><label>Description</label><textarea id="pageDesc">${esc(d.description||'')}</textarea></div><div class="field"><label>Page logo URL</label><input id="pageLogo" value="${esc(d.logo||'')}"></div><div class="field"><label>Payment methods</label><div id="paymentRows"></div><button type="button" class="btn ghost" id="addPayment">+ Add payment method</button></div>`;if(kind==='app')return `<div class="field"><label>Application store links (add at least one)</label><div id="appRows"></div><button type="button" class="btn ghost" id="addAppLink">+ Add app link</button></div>`;if(kind==='smartmap')return `<div class="field"><label>Company branches</label><div id="mapRows"></div><button type="button" class="btn ghost" id="addMapLink">+ Add branch</button><p class="hint">Add Google Maps destination URLs and optional latitude/longitude. GPS selects the nearest branch when coordinates are provided; otherwise the first branch is used.</p></div>`;return `<div class="field"><label>Video URL (YouTube, Facebook, Instagram or TikTok)</label><input id="videoUrl" type="url" value="${esc(d.videoUrl||'')}" placeholder="https://youtu.be/..."></div><p class="hint">A branded, responsive video page will be created. Platform autoplay and ad policies are controlled by the video provider and device browser.</p>`}
function drawPayments(){let r=$('#paymentRows');if(!r)return;r.innerHTML=payments.map((p,i)=>`<div class="pay-row"><input data-pname="${i}" placeholder="Method name" value="${esc(p.name)}"><input data-purl="${i}" placeholder="Payment URL" value="${esc(p.url)}"><input data-plogo="${i}" placeholder="Logo URL (optional)" value="${esc(p.logo||'')}"><button class="icon-btn" data-prem="${i}">${icon('fa-trash')}</button></div>`).join('');$$('[data-prem]').forEach(b=>b.onclick=()=>{payments.splice(+b.dataset.prem,1);drawPayments();updateDestinationPagePreview()});$$('[data-pname]').forEach(i=>i.oninput=()=>{payments[i.dataset.pname].name=i.value;updateDestinationPagePreview()});$$('[data-purl]').forEach(i=>i.oninput=()=>payments[i.dataset.purl].url=i.value);$$('[data-plogo]').forEach(i=>i.oninput=()=>payments[i.dataset.plogo].logo=i.value)}
function drawBankExtras(){let r=$('#bankExtraRows');if(!r)return;r.innerHTML=bankExtras.map((p,i)=>`<div class="pay-row bank-extra-row"><input data-bname="${i}" placeholder="Field label" value="${esc(p.label)}"><button class="icon-btn" data-copy-bname="${i}" title="Copy label">${icon('fa-copy')}</button><input data-bvalue="${i}" placeholder="Field value" value="${esc(p.value)}"><button class="icon-btn" data-copy-bvalue="${i}" title="Copy value">${icon('fa-copy')}</button><button class="icon-btn" data-bremove="${i}">${icon('fa-trash')}</button></div>`).join('');$$('[data-copy-bname]').forEach(b=>b.onclick=()=>copyText(bankExtras[+b.dataset.copyBname]?.label||''));$$('[data-copy-bvalue]').forEach(b=>b.onclick=()=>copyText(bankExtras[+b.dataset.copyBvalue]?.value||''));$$('[data-bremove]').forEach(b=>b.onclick=()=>{bankExtras.splice(+b.dataset.bremove,1);drawBankExtras();updateDestinationPagePreview()});$$('[data-bname]').forEach(i=>i.oninput=()=>bankExtras[i.dataset.bname].label=i.value);$$('[data-bvalue]').forEach(i=>i.oninput=()=>bankExtras[i.dataset.bvalue].value=i.value)}
function drawAppLinks(){let r=$('#appRows');if(!r)return;r.innerHTML=appLinks.map((p,i)=>`<div class="pay-row app-row"><span class="app-store-icon">${p.name==='Apple App Store'?'<i class="fa-brands fa-apple"></i>':p.name==='Google Play'?'<i class="fa-brands fa-google-play"></i>':icon('fa-mobile-screen-button')}</span><select data-aname="${i}"><option value="Apple App Store" ${p.name==='Apple App Store'?'selected':''}>Apple App Store</option><option value="Google Play" ${p.name==='Google Play'?'selected':''}>Google Play</option><option value="Other devices" ${p.name==='Other devices'?'selected':''}>Other devices</option></select><input data-aurl="${i}" placeholder="https://..." value="${esc(p.url||'')}"><button class="icon-btn" data-arem="${i}">${icon('fa-trash')}</button></div>`).join('');$$('[data-aname]').forEach(i=>i.onchange=()=>appLinks[i.dataset.aname].name=i.value);$$('[data-aurl]').forEach(i=>i.oninput=()=>appLinks[i.dataset.aurl].url=i.value);$$('[data-arem]').forEach(b=>b.onclick=()=>{appLinks.splice(+b.dataset.arem,1);drawAppLinks();updateDestinationPagePreview()})}
function drawMapLinks(){let r=$('#mapRows');if(!r)return;r.innerHTML=mapLinks.map((p,i)=>`<div class="map-row"><input data-mname="${i}" placeholder="Branch name" value="${esc(p.name||'')}"><input data-murl="${i}" placeholder="Google Maps URL" value="${esc(p.url||'')}"><input data-mlat="${i}" placeholder="Latitude (optional)" value="${esc(p.lat||'')}"><input data-mlng="${i}" placeholder="Longitude (optional)" value="${esc(p.lng||'')}"><button class="icon-btn" data-mrem="${i}">${icon('fa-trash')}</button></div>`).join('');$$('[data-mname]').forEach(i=>i.oninput=()=>mapLinks[i.dataset.mname].name=i.value);$$('[data-murl]').forEach(i=>i.oninput=()=>mapLinks[i.dataset.murl].url=i.value);$$('[data-mlat]').forEach(i=>i.oninput=()=>mapLinks[i.dataset.mlat].lat=i.value);$$('[data-mlng]').forEach(i=>i.oninput=()=>mapLinks[i.dataset.mlng].lng=i.value);$$('[data-mrem]').forEach(b=>b.onclick=()=>{mapLinks.splice(+b.dataset.mrem,1);drawMapLinks()})}
function readData(){if(kind==='url')return{url:$('#url').value.trim()};if(kind==='text')return{text:$('#text').value.trim()};if(kind==='phone')return{phone:$('#phone').value.trim()};if(kind==='bank')return{holder:$('#holder').value,bankName:$('#bankName').value,account:$('#account').value,branch:$('#branch').value,extra:$('#extra').value,extraFields:bankExtras};if(kind==='payments')return{title:$('#pageTitleInput').value,description:$('#pageDesc').value,logo:$('#pageLogo').value,payments};if(kind==='app')return{links:appLinks};if(kind==='smartmap')return{branches:mapLinks};return{videoUrl:$('#videoUrl').value.trim()}}
function payloadForQR(){return location.origin+'/go/'+draftId}
function currentStyle(){let logo=window.selectedLogo|| (editing?.style?.logo==='none'?'none':editing?.style?.logo==='custom'?'custom':'cladx');return{dot:$('#dotColor').value,corner:$('#cornerColor').value,cornerDot:$('#cornerDotColor').value,background:$('#bgColor').value,transparent:$('#transparentBg').checked,dotType:window.selectedPattern||editing?.style?.dotType||'rounded',cornerDotType:window.selectedFinderDot||editing?.style?.cornerDotType||'dot',cornerType:window.selectedFinderFrame||editing?.style?.cornerType||'extra-rounded',logo,customLogo:$('#customLogo')?.value||'',logoSize:Number($('#logoSize').value||.22)}}
function preview(){let stage=$('#qrStage');if(!stage||!window.QRCodeStyling)return;let st=currentStyle(),image=st.logo==='none'?undefined:st.logo==='custom'?st.customLogo:'/assets/qr-cladx-logo-icon.webp';stage.classList.toggle('transparent',!!st.transparent);qr=new QRCodeStyling({width:280,height:280,type:'canvas',data:payloadForQR(),margin:3,qrOptions:{errorCorrectionLevel:'H'},dotsOptions:{color:st.dot,type:st.dotType},backgroundOptions:{color:st.transparent?'rgba(0,0,0,0)':st.background},cornersSquareOptions:{color:st.corner,type:st.cornerType},cornersDotOptions:{color:st.cornerDot,type:st.cornerDotType},image,imageOptions:{crossOrigin:'anonymous',margin:3,imageSize:st.logoSize,hideBackgroundDots:true}});stage.innerHTML='';qr.append(stage)}
function updateDestinationPagePreview(){
let r=$('#destinationPagePreview');if(!r)return;
let data;try{data=readData()}catch{data={}};
const brand=`<img class="live-preview-logo" src="/assets/logo.webp" alt="CLADx">`;
let body='';
if(kind==='payments')body=`<h3>${esc(data.title||$('#qrName')?.value||'Multi Payments')}</h3><p>${esc(data.description||'Choose a payment method')}</p><div class="live-preview-payments">${(data.payments||[]).map(p=>`<div class="live-preview-row">${esc(p.name||'Payment method')} <span>↗</span></div>`).join('')||'<small>Add payment methods to preview them.</small>'}</div>`;
if(kind==='bank'){const rows=[['Account holder',data.holder],['Bank name',data.bankName],['Account / IBAN',data.account],['Branch / SWIFT',data.branch],['Additional details',data.extra],...(data.extraFields||[]).map(f=>[f.label,f.value])].filter(x=>x[1]);body=`<h3>${esc($('#qrName')?.value||'Bank details')}</h3><div class="live-preview-bank">${rows.map(x=>`<div><small>${esc(x[0]||'')}</small><b>${esc(x[1])}</b></div>`).join('')||'<small>Add account details to preview them.</small>'}</div>`}
if(kind==='app')body=`<h3>${esc($('#qrName')?.value||'Our app')}</h3><p>Choose your device store</p><div class="live-preview-payments">${(data.links||[]).filter(x=>x.url).map(x=>`<div class="live-preview-row">${esc(x.name)} <span>↗</span></div>`).join('')||'<small>Add at least one app link.</small>'}</div>`;
if(kind==='video')body=`<h3>${esc($('#qrName')?.value||'Video Marketing')}</h3><div class="live-preview-video"><i class="fa-solid fa-circle-play"></i><span>${esc(data.videoUrl||'Add a video URL to preview the destination page.')}</span></div>`;
r.innerHTML=`<div class="live-page-preview">${brand}${body}<div class="live-preview-footer">Provided by <b>CLADx</b></div></div>`;
}

async function saveQR(){let b=$('#saveQR'),name=$('#qrName').value.trim(),data=readData(),custom=slugify(customIdValue||$('#customId').value||slugify(name)+'-'+generatedSuffix);if(!name)return toast('Add a name first');customIdValue=custom;$('#customId').value=custom;let recordId=custom;draftId=recordId;if(items.some(x=>x.id===recordId&&x.id!==editing?.id))return toast('This short ID is already in use. Choose another.');if(editing)recordId=editing.id;
const valid=u=>/^https?:\/\//i.test(u||'');
if(kind==='url'&&!valid(data.url))return toast('Enter a valid http(s) URL');if(kind==='text'&&!data.text.trim())return toast('Enter text');if(kind==='phone'&&!data.phone.trim())return toast('Enter a phone number');if(kind==='bank'&&!data.account.trim())return toast('Enter an account number or IBAN');if(kind==='payments'&&(!data.payments.length||data.payments.some(p=>!p.name.trim()||!valid(p.url))))return toast('Add valid payment methods');if(kind==='app'&&(!data.links.length||!data.links.some(p=>valid(p.url))))return toast('Add at least one valid app store URL');if(kind==='smartmap'&&(!data.branches.length||data.branches.some(p=>!valid(p.url))))return toast('Add at least one valid branch map URL');if(kind==='video'&&!valid(data.videoUrl))return toast('Enter a valid video URL');if(!qr)return toast('QR generator is not ready');
let record={...(editing||{}),id:recordId,name,type:kind,data,style:currentStyle(),active:editing?.active!==false,updatedAt:Date.now(),createdAt:editing?.createdAt||Date.now()};
b.disabled=true;b.textContent='Saving…';try{let result=await api('links/'+record.id,{method:'PUT',body:JSON.stringify(record)}),saved=result.item||record;items=[saved,...items.filter(x=>x.id!==saved.id)];cache();editing=null;draftData={};draftName='';draftStyle=null;customIdValue='';customIdTouched=false;kind='url';draftId=saved.id;toast('QR and dynamic link saved to Cloudflare KV');go('codes')}catch(e){toast('Cloud save failed: '+e.message)}finally{if($('#saveQR')){b.disabled=false;b.textContent='Create QR'}}}
function downloadQr(ext){if(!qr)return toast('QR generator is not ready');if(ext==='svg'){qr.download({name:'cladx-qr-'+draftId,extension:'svg'});return}if(ext==='png'){qr.download({name:'cladx-qr-'+draftId,extension:'png'});return}let canvas=$('#qrStage canvas');if(!canvas)return toast('Canvas preview is not ready');let a=document.createElement('a');a.href=canvas.toDataURL('image/webp',.94);a.download='cladx-qr-'+draftId+'.webp';a.click()}
async function downloadPdf(){let canvas=$('#qrStage canvas');if(!canvas)return toast('QR preview not ready');if(!window.jspdf?.jsPDF)return toast('PDF library unavailable');let doc=new window.jspdf.jsPDF({orientation:'portrait',unit:'mm',format:'a4'});doc.setFontSize(18);doc.text($('#qrName').value||'QR Code',105,25,{align:'center'});doc.addImage(canvas.toDataURL('image/png'),'PNG',55,55,100,100);doc.save('cladx-qr-'+draftId+'.pdf')}
async function shareLink(){let url=payloadForQR(),title=$('#qrName').value||'QR experience';document.title=title+' | CLADx Privet QR';let meta=document.querySelector('meta[property="og:title"]');if(!meta){meta=document.createElement('meta');meta.setAttribute('property','og:title');document.head.append(meta)}meta.content=title;try{if(navigator.share)await navigator.share({title,text:title,url});else{await navigator.clipboard.writeText(url);toast('Share link copied')}}catch{}}
function mergeRecords(a,b){const m=new Map();[...(a||[]),...(b||[])].forEach(x=>{if(x?.id){let old=m.get(x.id);if(!old||(x.updatedAt||0)>=(old.updatedAt||0))m.set(x.id,x)}});return [...m.values()]}
function downloadBackup(data){let blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='cladx-privet-qr-backup.json';a.click();URL.revokeObjectURL(u)}
function backup(){$('#view').innerHTML=`<div class="grid backup-grid"><div class="card"><div class="eyebrow">CLOUD + LOCAL</div><h2>Backup now</h2><p class="hint">Merge and save records to Cloudflare KV and this device.</p><button class="btn" id="backupNow">Backup now</button><p class="hint" id="backupStatus"></p></div><div class="card"><div class="eyebrow">HOSTING</div><h2>Restore from hosting</h2><p class="hint">Restore the latest cloud snapshot to KV and local cache.</p><button class="btn ghost" id="restoreHosting">Restore from hosting</button></div><div class="card"><div class="eyebrow">OFFLINE COPY</div><h2>Import / export</h2><button class="btn ghost" id="export">Download backup</button><input type="file" id="importFile" accept="application/json"><button class="btn ghost" id="import">Import backup</button></div></div>`;
$('#backupNow').onclick=async()=>{let b=$('#backupNow');b.disabled=true;try{let local=JSON.parse(localStorage.getItem('cladx-privet-cache')||'[]'),merged=mergeRecords(items,local),r=await api('backup',{method:'POST',body:JSON.stringify({items:merged})});items=r.items||merged;cache();localStorage.setItem('cladx-privet-backup',JSON.stringify({createdAt:new Date().toISOString(),items}));$('#backupStatus').textContent='Backup saved to Cloudflare and local storage';toast('Backup completed')}catch(e){toast(e.message)}finally{b.disabled=false}};
$('#restoreHosting').onclick=async()=>{try{let d=await api('backup'),r=await api('backup',{method:'PUT',body:JSON.stringify({items:d.backup.items})});items=r.items;cache();localStorage.setItem('cladx-privet-backup',JSON.stringify(d.backup));toast('Backup restored');render()}catch(e){toast(e.message)}};
$('#export').onclick=()=>downloadBackup({items:mergeRecords(items,JSON.parse(localStorage.getItem('cladx-privet-cache')||'[]'))});$('#import').onclick=async()=>{let f=$('#importFile').files[0];if(!f)return toast('Choose a JSON file');try{let d=JSON.parse(await f.text()),r=await api('backup',{method:'PUT',body:JSON.stringify({items:d.items})});items=r.items;cache();toast('Imported');go('codes')}catch(e){toast(e.message)}}}
function settings(){$('#view').innerHTML=`<div class="card"><div class="eyebrow">WORKSPACE</div><h2>Private agency workspace</h2><p class="hint">Protected by the server-side admin password. Cloudflare Pages Secrets: ADMIN_PASSWORD and SESSION_SECRET.</p><div class="field"><label>Public base URL</label><input readonly value="${location.origin}"></div><div class="field"><label>KV binding</label><input readonly value="QR_KV"></div></div>`}
async function loadNotificationCount(){try{let d=await api('notifications');let el=$('#notifyCount');if(el)el.textContent=(d.notifications||[]).length}catch{}}
async function showNotifications(){try{let d=await api('notifications');$('#view').innerHTML=`<div class="section-head"><div><h2>Notifications</h2><p>QR scans and usage thresholds.</p></div></div><div class="card">${(d.notifications||[]).map(n=>`<div class="notification-row"><img class="notification-image" src="/assets/notifications.webp" alt=""><div><b>${esc(n.title)}</b><p>${esc(n.message)}</p><small>${new Date(n.createdAt).toLocaleString()}</small></div></div>`).join('')||'No notifications yet.'}</div>`;active='notifications';$('#pageTitle').textContent='Notifications';applyLanguage()}catch(e){toast(e.message)}}
function showAbout(){ $('#view').innerHTML=`<div class="card"><h2>CLADx Privet QR</h2><p>Dynamic QR management for CLADx agency clients.</p><a href="https://cladxagency.com" target="_blank" rel="noopener">CLADx Agency</a></div>`;active='about';$('#pageTitle').textContent='About project';applyLanguage()}
async function init(){token=sessionStorage.getItem('cladx-session')||'';if(token){try{await api('auth/me');await load();render();return}catch{token='';sessionStorage.removeItem('cladx-session')}}login()}
init();
})();